public class Z3SummaryInformationPanel : JPanel {

	class InfoKind
{	public static readonly InfoKind VALUATION = new();
	public static readonly InfoKind PRECONDITION = new();


		string display;

		private InfoKind(string display) {
			this.display = display;
		}

		/* @Override */
		public string toString() {
			return display;
		}
	}

	record InformationRow(InfoKind kind, string variable, string value) {}

	private static readonly MonospaceCellRenderer MONO_RENDERER = new MonospaceCellRenderer();

	protected class InformationTableColumns : EnumeratedTableColumn<InformationTableColumns, InformationRow>
{	public static readonly InformationTableColumns KIND = new(, typeof(InfoKind), InformationRow.kind);
	public static readonly InformationTableColumns VARIABLE = new(, typeof(string), InformationRow.variable);
	public static readonly InformationTableColumns VALUE = new(, typeof(string), InformationRow.value);


		private string header;
		private Class<object> cls;
		private Function<InformationRow,object> getter;

		<T> InformationTableColumns(string header, Class<T> cls,
				Function<InformationRow, T> getter) {
			this.header = header;
			this.cls = cls;
			this.getter = getter;
		}

		/* @Override */
		public string getHeader() {
			return header;
		}

		/* @Override */
		public Class<object> getValueClass() {
			return cls;
		}

		/* @Override */
		public object getValueOf(InformationRow row) {
			return getter.apply(row);
		}
	}

	protected static class InformationTableModel : DefaultEnumeratedColumnTableModel<InformationTableColumns, InformationRow> {
